/**
 * Finds the majority element in an integer array using the Boyer-Moore Voting Algorithm.
 * The majority element is defined as the element that appears more than n/2 times in the array.
 * This function operates in O(n) time complexity and O(1) space complexity.
 * 
 * @param {number[]} nums - The input integer array.
 * @return {number} The majority element if it exists, otherwise returns -1.
 */
function findMajorityElement(nums) {
    let count = 0;
    let candidate = null;

    for (const num of nums) {
        if (count === 0) {
            candidate = num;
        }
        count += (num === candidate) ? 1 : -1;
    }

    // Verify if the candidate is indeed the majority element
    if (nums.filter(x => x === candidate).length > nums.length / 2) {
        return candidate;
    } else {
        return -1;
    }
}

