/**
 * Finds the top 2 most occurring elements in an integer array.
 * This function operates in O(n) time complexity and O(1) space complexity.
 * 
 * @param {number[]} nums - The input integer array.
 * @return {number[]} The top 2 most occurring elements.
 */
function findTop2Elements(nums) {
    let count = {};
    let result = [];

    for (const num of nums) {
        if (count[num]) {
            count[num]++;
        } else {
            count[num] = 1;
        }
    }

    // Sort the elements based on their counts in descending order
    const sortedElements = Object.entries(count).sort((a, b) => b[1] - a[1]);

    // Take top 2 elements
    for (let i = 0; i < 2 && i < sortedElements.length; i++) {
        result.push(parseInt(sortedElements[i][0]));
    }

    return result;
}

